+/**
+ * The day book: one line to a handing-over, added as seed goes out of the
+ * drawer.
+ *
+ * `noted` is the line one handing-over is written as, and `handedOut` is the
+ * day book's text read back into those lines, in the order they were
+ * written, with the blank ones left out. Nothing here touches disk — that is
+ * `Store.handOut`'s business.
+ */
+
+/** The name of the file the day book is written in, in the store's own root. */
+export const DAYBOOK = ".daybook";
+
+/** One line of the day book: what went out of a packet, and what was left. */
+export function noted(name: string, seeds: number, left: number): string {
+  return `${name}: ${seeds} out, ${left} left`;
+}
+
+/** The lines a day book's text holds, in the order they were written, with
+ * the blank ones left out. */
+export function handedOut(text: string): string[] {
+  return text.split("\n").filter((line) => line !== "");
+}
