+/**
+ * A correction: a ticket's figures put right, without scratching out what
+ * the tape already says.
+ *
+ * The yard does not write over a weighing — what was written is what was
+ * written. Where a figure was wrong, a correction goes on the tape after it,
+ * against the same ticket, and the tape is read with the last word standing.
+ * A correction does not carry a haulier: the ticket it corrects already says
+ * whose lorry it was.
+ *
+ * A correction takes the same frame every other frame does, at the same
+ * width, with its own kind byte at the front of it.
+ */
+
+import { Buffer } from "node:buffer";
+
+import {
+  FRAME_BYTES,
+  GROSS_AT,
+  KIND_AT,
+  NOTHING_OF_THE_KIND,
+  TARE_AT,
+  TICKET_AT,
+  kindOf,
+} from "./frames.ts";
+
+/** The kind byte a correction's own frame carries. */
+export const A_CORRECTION = 2;
+
+export class Correction {
+  readonly ticket: number;
+  readonly grossKg: number;
+  readonly tareKg: number;
+
+  constructor(ticket: number, grossKg: number, tareKg: number) {
+    this.ticket = ticket;
+    this.grossKg = grossKg;
+    this.tareKg = tareKg;
+  }
+
+  /** What the load comes to once it is allowed for. */
+  netKg(): number {
+    return this.grossKg - this.tareKg;
+  }
+}
+
+/** One correction, as it goes on the tape. */
+export function correctionFrame(correction: Correction): Buffer {
+  const frame = Buffer.alloc(FRAME_BYTES);
+  frame.writeUInt8(A_CORRECTION, KIND_AT);
+  frame.writeUInt32BE(correction.ticket, TICKET_AT);
+  frame.writeUInt32BE(correction.grossKg, GROSS_AT);
+  frame.writeUInt32BE(correction.tareKg, TARE_AT);
+  return frame;
+}
+
+/** The correction a frame holds, or nothing where the frame is of another
+ * kind or is not a frame at all. */
+export function correctionIn(frame: Buffer): Correction | null {
+  if (kindOf(frame) !== A_CORRECTION) {
+    return NOTHING_OF_THE_KIND;
+  }
+  return new Correction(
+    frame.readUInt32BE(TICKET_AT),
+    frame.readUInt32BE(GROSS_AT),
+    frame.readUInt32BE(TARE_AT),
+  );
+}
